  if(forzar!=="es") traduce("en"); else pintaVault();
  /* v4 · el paso 2 precalifica: edad, ocupacion y disposicion a viajar. */
  var SERVICIO={es:"Evaluación ($400 USD) · después, programa ($13,000 USD)",
                en:"Evaluation ($400 USD) · then programme ($13,000 USD)"};
  var estado={busca:null,enviado:false,enviadoC:false};
  /* ── ENVIO · VALOR DE PRUEBA (13-sep-2026) ─────────────────────────────────
