      <span>ZAFIRA</span>
    </div>
    <div style="display:flex;align-items:center;gap:18px">
      <div class="menu"><a href="#metodo" data-ancla="metodo" data-es="El proceso" data-en="The process">El proceso</a><a href="#criterio" data-ancla="criterio" data-es="El criterio" data-en="Our judgment">El criterio</a><a href="#discrecion" data-ancla="discrecion" data-es="Discreción" data-en="Discretion">Discreción</a></div>
      <button class="btn nav-cta" data-es="Comprobar si califico" data-en="See if I qualify">Comprobar si califico</button><div class="lang"><button data-lang="en">EN</button><button data-lang="es" class="on">ES</button></div>
