  var PERFILES=[[26,"Cartagena"],[29,"Medellín"],[24,"Bogotá"],[28,"Cali"],[25,"Pereira"],[31,"Armenia"]];
  var T={es:{res:"Perfil reservado"}, en:{res:"Reserved profile"}};
  var lang="es";
  var forzar = (typeof navigator!=="undefined" && /^es/i.test(navigator.language||"")) ? "es" : "en";

  function pintaVault(){
    document.querySelectorAll("[data-vault]").forEach(function(grid){
      grid.innerHTML="";
      PERFILES.forEach(function(p,i){
        var c=document.createElement("article");
        c.className="card"; c.dataset.state="default"; c.tabIndex=0;
        c.setAttribute("role","button"); c.setAttribute("aria-pressed","false");
        c.setAttribute("aria-label", p[0]+" — "+p[1]);
        c.innerHTML='<div class="imgwrap"><img src="'+IMGS[i]+'" alt="" aria-hidden="true">'+
          '<div class="ov"><svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="#C9A84C" stroke-width="1.5" stroke-linecap="round"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg><span data-ov>'+T[lang].res+'</span></div>'+
          '</div><div class="info">'+p[0]+' · '+p[1]+'</div>';
        function ver(){ c.dataset.state="revealed"; c.setAttribute("aria-pressed","true"); }
        function velar(){ c.dataset.state="default"; c.setAttribute("aria-pressed","false"); }
        /* v9 · en tactil mouseenter y click llegan en el mismo toque: revelaba y
           volvia a velar. El hover solo cuenta donde hay puntero con hover. */
        if(window.matchMedia&&window.matchMedia("(hover:hover)").matches){
          c.addEventListener("mouseenter",ver);
          c.addEventListener("mouseleave",velar);
        }
        c.addEventListener("focus",ver);
        c.addEventListener("blur",velar);
        c.addEventListener("click",function(){ var r=c.dataset.state!=="revealed"; c.dataset.state=r?"revealed":"default"; c.setAttribute("aria-pressed",String(r)); });
        c.addEventListener("keydown",function(e){ if(e.key==="Enter"||e.key===" "){ e.preventDefault(); c.click(); } });
        grid.appendChild(c);
      });
    });
  }
  function traduce(l){
    lang=l;
    document.documentElement.lang=l;
    document.querySelectorAll("[data-es]").forEach(function(el){
      var v=el.getAttribute("data-"+l);
      if(v===null || el.children.length) return;
      el.textContent=v;
    });
    document.querySelectorAll(".lang button").forEach(function(b){
      b.classList.toggle("on",b.dataset.lang===l);
    });
    document.querySelectorAll("[data-href-es]").forEach(function(a){
      var h=a.getAttribute("data-href-"+l); if(h) a.setAttribute("href",h);
    });
    document.querySelectorAll("[data-aria-es]").forEach(function(el){
      var v=el.getAttribute("data-aria-"+l); if(v) el.setAttribute("aria-label",v);
    });
    document.querySelectorAll("[data-alt-es]").forEach(function(el){
      var v=el.getAttribute("data-alt-"+l); if(v) el.setAttribute("alt",v);
    });
    pintaVault();
  }
  document.querySelectorAll(".lang button").forEach(function(b){
    b.addEventListener("click",function(){traduce(b.dataset.lang);});
  });


  if(forzar!=="es") traduce("en"); else pintaVault();
  /* v4 · el paso 2 precalifica: edad, ocupacion y disposicion a viajar. */
  var SERVICIO={es:"Evaluación ($400 USD) · después, programa ($13,000 USD)",
