        <h2 class="tit" style="margin:0" data-es="Esto no es para todo el mundo." data-en="This is not for everyone.">Esto no es para todo el mundo.</h2>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:30px" class="quees">
