<!-- 4 · MÉTODO -->
<div style="background:#12100B">
  <div class="wrap">
    <section class="blq" id="metodo">

      <h2 class="tit" style="margin-bottom:10px" data-es="El camino, en cinco pasos" data-en="The path, in five steps">El camino, en cinco pasos</h2>
      <p class="lead" style="margin-bottom:30px" data-es="Solicitud sin costo → revisión preliminar → $400 USD de evaluación y verificación → aprobación → $13,000 USD del programa. En ese orden, y no hay otro." data-en="Free application → preliminary review → $400 USD evaluation and verification → approval → $13,000 USD programme. In that order, and there is no other.">Solicitud sin costo → revisión preliminar → $400 USD de evaluación y verificación → aprobación → $13,000 USD del programa. En ese orden, y no hay otro.</p>
      <div class="grid5">
        <div class="paso act"><div class="n">01</div><h3 data-es="Solicitud" data-en="Application">Solicitud</h3><p data-es="Cuatro minutos y sin costo. Nos dice quién es y qué busca. Enviarla no genera ningún cobro." data-en="Four minutes, at no cost. You tell us who you are and what you are looking for. Sending it triggers no charge.">Cuatro minutos y sin costo. Nos dice quién es y qué busca. Enviarla no genera ningún cobro.</p></div>
        <div class="paso"><div class="n">02</div><h3 data-es="Revisión preliminar" data-en="Preliminary review">Revisión preliminar</h3><p data-es="La leemos nosotros. Si el perfil no encaja, se lo decimos ahí mismo y no le hemos cobrado nada." data-en="We read it ourselves. If the profile is not a fit, we tell you right there, and you have paid nothing.">La leemos nosotros. Si el perfil no encaja, se lo decimos ahí mismo y no le hemos cobrado nada.</p></div>
        <div class="paso"><div class="n">03</div><h3 data-es="Evaluación y verificación" data-en="Evaluation and verification">Evaluación y verificación</h3><p data-es="$400 USD. Entrevista, identidad y antecedentes. Se paga aquí, cuando le decimos que su perfil puede avanzar." data-en="$400 USD. Interview, identity and background. Paid here, once we tell you your profile can move forward.">$400 USD. Entrevista, identidad y antecedentes. Se paga aquí, cuando le decimos que su perfil puede avanzar.</p></div>
        <div class="paso"><div class="n">04</div><h3 data-es="Aprobación" data-en="Approval">Aprobación</h3><p><span data-es="Se decide si entra al programa. Pagar la evaluación no es entrar." data-en="We decide whether you join the programme. Paying for the evaluation is not joining.">Se decide si entra al programa. Pagar la evaluación no es entrar.</span> <span data-es="Si no lo aprueban, los $400 no se devuelven: pagan el estudio, y el estudio se hizo." data-en="If you are not approved, the $400 are not returned: they pay for the review, and the review was done.">Si no lo aprueban, los $400 no se devuelven: pagan el estudio, y el estudio se hizo.</span></p></div>
        <div class="paso"><div class="n">05</div><h3 data-es="El programa" data-en="The programme">El programa</h3><p data-es="$13,000 USD. Búsqueda personalizada, presentaciones y acompañamiento, con el encuentro de Cartagena dentro." data-en="$13,000 USD. A search run for you, introductions and guidance, with the Cartagena gathering inside it.">$13,000 USD. Búsqueda personalizada, presentaciones y acompañamiento, con el encuentro de Cartagena dentro.</p></div>
