    caja.addEventListener("keydown",function(e){
      if(e.key!=="Tab")return;
      var f=[...caja.querySelectorAll('button,input,select,a[href],[tabindex]:not([tabindex="-1"])')]
              .filter(function(x){return x.offsetParent!==null;});
      if(!f.length)return;
      var pri=f[0], ult=f[f.length-1];
      if(e.shiftKey && document.activeElement===pri){ e.preventDefault(); ult.focus(); }
      else if(!e.shiftKey && document.activeElement===ult){ e.preventDefault(); pri.focus(); }
    });
  }
  [mfondo,mfondoC].forEach(function(m){ if(m) atrapaFoco(m.querySelector(".mcaja")); });
  function bloquea(si){
    var l=document.getElementById("lienzo");
    document.body.style.overflow = si ? "hidden" : "";
    if(l) l.style.overflow = si ? "hidden" : "";
  }
  function limpia(){
    /* v9 · tras una solicitud enviada, reabrir no reenvia lo mismo */
    if(estado.enviado){
      document.querySelectorAll("[data-campo]").forEach(function(e){ e.value=""; });
      document.querySelectorAll(".mop").forEach(function(x){x.classList.remove("sel");});
      estado.busca=null; estado.enviado=false; vePaso(1);
    }
    if(estado.enviadoC){
      document.querySelectorAll("[data-campoc]").forEach(function(e){ e.value=""; });
      estado.enviadoC=false; if(mfondoC) vePaso(1, mfondoC.querySelector(".mcaja"));
    }
  }
  function cierra(){
    [mfondo,mfondoC].forEach(function(m){ if(m) m.hidden=true; });
    bloquea(false); limpia();
    if(abridor && abridor.focus) abridor.focus();
    abridor=null;
  }

  document.querySelectorAll(".mcerrar,.mcerrar2").forEach(function(b){b.addEventListener("click",cierra);});
  [mfondo,mfondoC].forEach(function(m){
    if(!m) return;
    var bajoFuera=false;
    m.addEventListener("mousedown",function(e){ bajoFuera=(e.target===m); });
    m.addEventListener("click",function(e){ if(e.target===m&&bajoFuera) cierra(); bajoFuera=false; });
  });
  document.addEventListener("keydown",function(e){ if(e.key==="Escape") cierra(); });

  document.querySelectorAll(".mop").forEach(function(b){
    b.addEventListener("click",function(){
      document.querySelectorAll(".mop").forEach(function(x){x.classList.remove("sel");});
      b.classList.add("sel"); estado.busca=b.dataset.val;
      setTimeout(function(){vePaso(2);},170);
    });
  });
  /* no se avanza con los datos que hacen falta para responder */
  document.querySelectorAll(".madelante").forEach(function(b){
    b.addEventListener("click",function(){
      var correo=val("correo");
      var correoOk=/^[^@\s]+@[^@\s.][^@\s]*\.[A-Za-z]{2,}$/.test(correo)&&correo.indexOf("..")<0;
      var edadN=Number(val("edad"));
      var edadOk=/^\d{2}$/.test(val("edad"))&&edadN>=18&&edadN<=99;
      var telOk=(val("tel").replace(/\D/g,"").length>=7);
      /* Los campos llevan `required`, pero aquí no hay <form> que lo haga valer:
         si la validación no los mira, el atributo es decorativo y se avanza con
         el paso vacío. Se comprueban los mismos que están marcados. */
      var vacio=!val("nombre")||!val("correo")||!val("tel")||!val("edad")||!val("ocupacion");
      var falta=vacio||!correoOk||!edadOk||!telOk;
      var err=document.getElementById("merror");
      if(falta){
        var clave = vacio ? "" : !correoOk ? "-correo" : !edadOk ? "-edad" : "-tel";
        if(err) err.hidden=false;
        if(err) err.textContent = err.getAttribute("data-"+lang+clave);
        var foco = !val("nombre")    ? '[data-campo="nombre"]'
                 : !correoOk         ? '[data-campo="correo"]'
                 : !telOk            ? '[data-campo="tel"]'
                 : !edadOk           ? '[data-campo="edad"]' : '[data-campo="ocupacion"]';
        var e=document.querySelector(foco); if(e) e.focus();
        return;
      }
      if(err) err.hidden=true;
      vePaso(3);
    });
  });
  document.querySelectorAll(".matras").forEach(function(b){
    b.addEventListener("click",function(){
      var act=document.querySelector("#mfondo .mpaso.on");
      vePaso(Math.max(1,parseInt(act.dataset.paso,10)-1));
    });
  });
  document.querySelectorAll(".menviar").forEach(function(b){b.addEventListener("click",function(){
    if(estado.enviado) { vePaso(4); return; }
    b.disabled=true;
    envia("application", estado.filas||[], lang==="es"?"Solicitud · Zafira":"Application · Zafira", function(porCorreo){
      estado.enviado=true; b.disabled=false; notaEnvio("menvio-nota", porCorreo); vePaso(4);
    });
  });});
  document.querySelectorAll(".menviar-c").forEach(function(b){
    b.addEventListener("click",function(){
      var caja=mfondoC.querySelector(".mcaja");
      var vc=function(c){var e=document.querySelector('[data-campoc="'+c+'"]');return e?e.value.trim():"";};
      var vacio=["nombre","ciudad","edad","tel"].some(function(c){return !vc(c);});
      var edadOk=/^\d{2}$/.test(vc("edad"))&&Number(vc("edad"))>=18&&Number(vc("edad"))<=99;
      var telOk=vc("tel").replace(/\D/g,"").length>=7;
      var err=document.getElementById("merror-c");
      if(vacio||!edadOk||!telOk){
        var clave = vacio ? "" : !edadOk ? "-edad" : "-tel";
        if(err){ err.hidden=false; err.textContent=err.getAttribute("data-"+lang+clave); }
        return;
      }
      if(err) err.hidden=true;
      if(estado.enviadoC){ vePaso(2, caja); return; }
      var t=TXT[lang];
      var filas=[[t.nombre,vc("nombre")],[t.ciudad,vc("ciudad")],[t.edad,vc("edad")],["WhatsApp",vc("tel")]];
      envia("candidate", filas, lang==="es"?"Registro de candidata · Zafira":"Candidate registration · Zafira", function(porCorreo){
        estado.enviadoC=true; notaEnvio("menvio-nota-c", porCorreo); vePaso(2, caja);
      });
    });
  });

  /* CTA: el del lado de candidatas abre SU formulario, no el del comprador */
  document.querySelectorAll(".btn,[data-flujo]").forEach(function(b){
    if(b.closest(".mcaja")||b.hasAttribute("data-wa")||b.dataset.enganchado)return;
    b.dataset.enganchado="1";
    var esCand = b.closest("#rec-damas") || b.dataset.flujo==="candidata";
    b.addEventListener("click",function(){ esCand ? abreC() : abre(1); });
  });

  /* navegación superior y pie: solo las anclas se interceptan; /blog/ y las
     políticas son enlaces reales del sitio y navegan (en la v6 quedaban muertos). */
  document.querySelectorAll(".menu a[data-ancla], footer .links a[data-ancla]").forEach(function(a){
    a.addEventListener("click",function(e){
      var el=document.getElementById(a.getAttribute("data-ancla"));
      if(!el) return;
      e.preventDefault();
      var cont=document.getElementById("lienzo");
      if(document.body.classList.contains("movil")&&cont){
        cont.scrollTo({top:el.offsetTop-20,behavior:"smooth"});
      } else { el.scrollIntoView({behavior:"smooth",block:"start"}); }
    });
  });

})();
</script>

</div>
</body>
